// GCC -fprofile-generate/use - profile-guided decision demo
var profile = { "hot:render": 9500, "cold:init": 12, "warm:parse": 800 };
function decide(fn) {
  var hits = profile[fn] || 0;
  if (hits > 5000) return "compile -O3 + inline aggressively";
  if (hits > 100) return "compile -O2";
  return "compile -Os (cold)";
}
console.log("Technique: instrumented PGO | Toolchain: GCC");
Object.keys(profile).forEach(function(f) { console.log("  " + f + " (" + profile[f] + " hits) -> " + decide(f)); });
console.log("Hot path gets max optimization -> PASS");

